-- 목적: view_item/add_to_cart 이벤트가 목록 경로(add_to_cart 10건 이상 경로 + store/asearch)에서 찍혔는지 vs 그 외 경로에서 찍혔는지, 아이템 수 분포 (12/1~1/11).
SELECT event_name,
  LOWER(REGEXP_EXTRACT((SELECT value.string_value FROM UNNEST(event_params) WHERE key = 'page_location'), r'^https?://[^/]+(/[^?#]*)')) IN ('/asearch.html','/google+redesign/apparel','/google+redesign/apparel/hats','/google+redesign/apparel/kids','/google+redesign/apparel/kids/kids+infant','/google+redesign/apparel/mens','/google+redesign/apparel/mens/mens+t+shirts','/google+redesign/apparel/socks','/google+redesign/apparel/womens','/google+redesign/bags/backpacks/','/google+redesign/campus+collection','/google+redesign/clearance','/google+redesign/drinkware/mugs+tumblers','/google+redesign/eco+friendly','/google+redesign/gift+cards','/google+redesign/lifestyle','/google+redesign/lifestyle/bags','/google+redesign/lifestyle/drinkware','/google+redesign/lifestyle/small+goods','/google+redesign/new','/google+redesign/office','/google+redesign/shop+by+brand','/google+redesign/shop+by+brand/android','/google+redesign/shop+by+brand/google','/google+redesign/shop+by+brand/google+cloud','/google+redesign/shop+by+brand/i+am+remarkable','/google+redesign/shop+by+brand/youtube','/google+redesign/stationery','/google+redesign/stationery/notebooks','/google+redesign/stationery/stickers','/google+redesign/stationery/writing','/store.html') AS on_list_path,
  CASE WHEN ARRAY_LENGTH(items) = 0 THEN '0개' WHEN ARRAY_LENGTH(items) < 6 THEN '1~5개' ELSE '6개 이상' END AS item_bucket,
  COUNT(*) AS events
FROM `bigquery-public-data.ga4_obfuscated_sample_ecommerce.events_*`
WHERE _TABLE_SUFFIX BETWEEN '20201201' AND '20210111' AND event_name IN ('view_item', 'add_to_cart')
GROUP BY event_name, on_list_path, item_bucket ORDER BY event_name, on_list_path, item_bucket
